const body = $json.body ?? $json;
const tag = body.tag && typeof body.tag === 'object' ? body.tag : {};
const statusValue = body.status && typeof body.status === 'object' ? body.status.label : body.status;
const eventType = String(body.event_type || body.eventType || '').trim().toLowerCase();
const occurredAt = String(body.occurred_at || body.occurredAt || new Date().toISOString());
const chatId = String(body.chat_id || body.chatId || body.phone || '');
const contactId = String(body.contact_id || body.contactId || chatId || body.contact_airtable_id || '');
const messageId = String(body.message_id || body.messageId || '');
const tagId = String(tag.id || body.tag_id || body.tagId || '');
const stableTarget = messageId || tagId || String(statusValue || '') || contactId;
const eventId = String(body.event_id || body.eventId || (messageId ? `message:${messageId}` : `${eventType}:${stableTarget}:${occurredAt}`));

return [{ json: {
  eventId,
  eventType,
  occurredAt,
  contactId,
  contactAirtableId: String(body.contact_airtable_id || body.contactAirtableId || ''),
  chatId,
  contactName: String(body.contact_name || body.contactName || body.nome_contato || body.name || ''),
  contactPhone: String(body.contact_phone || body.contactPhone || body.phone || chatId),
  messageId,
  messageText: String(body.message_text || body.messageText || body.received || body.concatenated_text || ''),
  tagId,
  tagLabel: String(tag.label || body.tag_label || body.tagLabel || ''),
  status: String(statusValue || ''),
  previousStatus: String(body.previous_status || body.previousStatus || body.previous?.status || ''),
  routineId: String(body.routine_id || body.routineId || ''),
  correlationId: String(body.correlation_id || body.correlationId || eventId),
  causationId: String(body.causation_id || body.causationId || ''),
  source: String(body.source || 'n8n')
} }];
